package com.hrtbuddy; import android.content.*; import android.app.*; import android.os.Build; public class BootReceiver extends BroadcastReceiver { public void onReceive(Context c,Intent i){ if(Build.VERSION.SDK_INT>=26){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("hrt_v2","HRT reminders",NotificationManager.IMPORTANCE_HIGH));} ReminderReceiver.schedule(c); } }
